export default function (input) {
  const now = new Date(input.now);
  const lagos = new Date((isNaN(now.getTime()) ? new Date() : now).getTime() + 3600 * 1000);
  return { date: lagos.toISOString().slice(0, 10) };
}

function naira(n) { return 'NGN ' + Number(n).toLocaleString('en-NG', { minimumFractionDigits: 0, maximumFractionDigits: 2 }); }
function latestByReference(rows) {
  const by = {};
  for (const r of rows || []) {
    if (!r || !r.reference) continue;
    const seen = by[r.reference];
    if (!seen || String(r.happened_at || '') >= String(seen.happened_at || '')) by[r.reference] = r;
  }
  return Object.keys(by).map(function (k) { return by[k]; });
}
export default function (input) {
  const asked = String(input.terminal || '').trim().toLowerCase();
  let serial = asked, label = String(input.terminal || '').trim();
  for (const t of input.terminals || []) {
    if (!t) continue;
    if (String(t.serial || '').toLowerCase() === asked || String(t.name || '').toLowerCase() === asked) { serial = String(t.serial).toLowerCase(); label = t.name ? String(t.name) : String(t.serial); break; }
  }
  let total = 0, count = 0;
  for (const s of latestByReference(input.rows)) {
    if (!s.approved || String(s.terminal || '').toLowerCase() !== serial) continue;
    const a = Number(s.amount); if (!isFinite(a)) continue;
    total += a; count += 1;
  }
  const book = Number(input.book_total); const bookTotal = isFinite(book) ? book : 0;
  const difference = Math.round((bookTotal - total) * 100) / 100;
  let verdict = 'They match.';
  if (difference > 0) verdict = 'The sales book is ' + naira(difference) + ' more than the terminal took: look for sales not paid by POS, or payments that did not go through.';
  if (difference < 0) verdict = 'The terminal took ' + naira(-difference) + ' more than the sales book shows: look for sales not written down.';
  const message = input.business_name + ' cash-up for ' + label + ', ' + input.date + ': terminal ' + naira(total) + ' (' + count + ' sale(s)), sales book ' + naira(bookTotal) + '. ' + verdict;
  return { terminal: serial, label: label, pos_total: Math.round(total * 100) / 100, count: count, book_total: bookTotal, difference: difference, message: message };
}
